/** Free AEO/GEO audit report — generated by Gemini research, no live Scrunch API call. */

import type { ScrunchBrandSetupDoc } from "@/lib/scrunch-setup-types";

export const AEO_PLATFORM_TOKENS =
  "chatgpt, claude, google_ai_overviews, google_ai_mode, perplexity, grok, google_gemini, copilot, meta";

export type AeoReadinessRating = "Strong" | "Developing" | "At risk";

export type AeoAuditPersona = { name: string; description: string };
export type AeoAuditTopic = { name: string; description: string };
export type AeoAuditCompetitor = {
  name: string;
  website: string;
  whyInScope: string;
};
export type AeoAuditPromptStage =
  | "Awareness"
  | "Consideration"
  | "Conversion"
  | "Loyalty"
  | "Other";
export type AeoAuditPrompt = {
  prompt: string;
  persona: string;
  topic: string;
  stage: AeoAuditPromptStage;
  branded: boolean;
};
export type AeoAuditHypothesis = {
  expect: string;
  because: string;
  confirmedBy: string;
  refutedBy: string;
};

export type CitationPrompt = {
  prompt: string;
  note: string;
};

export type MentionRateRow = {
  name: string;
  website: string;
  estimatedPct: number;
  isAuditedBrand: boolean;
};

export type MentionRateSnapshot = {
  brandName: string;
  website: string;
  citationPrompts: CitationPrompt[];
  mentionRates: MentionRateRow[];
  generatedAt: string;
};

export type VisibilityBand = "Below average" | "Average" | "Healthy";
export type VisibilityPositionBand = "Top" | "Mid" | "Low";
export type VisibilitySentiment = "Positive" | "Mixed" | "Negative";

export type VisibilityCompetitor = {
  name: string;
  presencePct: number;
  gapPts: number;
  isYou: boolean;
};

export type VisibilityLostPrompt = {
  prompt: string;
  fillingBrand: string;
  fillingPct: number;
};

export type VisibilityPlatform = {
  name: string;
  presencePct: number;
  position: VisibilityPositionBand;
  sentiment: VisibilitySentiment;
};

export type VisibilitySource = {
  source: string;
  estimatedCitations: number;
};

/** Research-based lookalike of a Scrunch AI Visibility Report — not a live 30-day monitor. */
export type VisibilityBrief = {
  score: number;
  presencePct: number;
  positionScore: number;
  citationSharePct: number;
  sentimentScore: number;
  headline: string;
  presenceBand: VisibilityBand;
  positionBand: VisibilityBand;
  citationBand: VisibilityBand;
  sentimentBand: VisibilityBand;
  competitorPresence: VisibilityCompetitor[];
  lostPrompts: VisibilityLostPrompt[];
  platforms: VisibilityPlatform[];
  narrative: {
    ownedPct: number;
    lostToCompetitorsPct: number;
    mentionOpportunitiesPct: number;
  };
  ownedUrls: VisibilitySource[];
  competitorDomains: VisibilitySource[];
  mentionOpportunities: VisibilitySource[];
};

export type StoredVisibilityReport = {
  id: string;
  email: string;
  name: string;
  company: string;
  brandName: string;
  website: string;
  createdAt: string;
  updatedAt: string;
  visibility: VisibilityBrief;
  citationPrompts: CitationPrompt[];
  mentionRates: MentionRateRow[];
};

export type AeoAuditCounts = {
  topics: number;
  competitors: number;
  personas: number;
  prompts: number;
  nonBrandedPct: number;
  platforms: number;
};

export type AeoLead = {
  name: string;
  company: string;
  email: string;
};

export type { BoothEventCode } from "@/lib/booth-events";

/** Result of a stand-desk Scrunch org/brand lookup — ids only, no workflow flags. */
export type ScrunchBrandCheck = {
  configured: boolean;
  found: boolean;
  orgId: string;
  brandId: string;
  brandName: string;
  website: string;
  message: string;
};

/** One booth audit in Firestore `tmf_scrunch_leads` — keyed by website (and the stand-desk UI). */
export type StoredBoothLead = {
  id: string;
  name: string;
  company: string;
  email: string;
  aeName: string;
  aeEmail: string;
  auditedBrand: string;
  auditedWebsite: string;
  eventCode: string;
  eventName: string;
  scrunchOrgId: string;
  scrunchBrandId: string;
  scrunchBrandName: string;
  createdAt: string;
  updatedAt: string;
  auditCount: number;
  lastReport: MentionRateSnapshot | null;
  hasScrunchPdf: boolean;
  scrunchPdfFilename: string;
  scrunchPdfUploadedAt: string;
  archived: boolean;
  reportHidden: boolean;
  scrunchSetup: ScrunchBrandSetupDoc | null;
};

export type AeoAuditReport = {
  brandName: string;
  website: string;
  primaryCountry: string;
  primaryCountryLabel: string;
  description: string;
  readiness: AeoReadinessRating;
  readinessSummary: string;
  competitors: AeoAuditCompetitor[];
  personas: AeoAuditPersona[];
  topics: AeoAuditTopic[];
  prompts: AeoAuditPrompt[];
  hypotheses: AeoAuditHypothesis[];
  citationPrompts: CitationPrompt[];
  mentionRates: MentionRateRow[];
  visibility: VisibilityBrief | null;
  counts: AeoAuditCounts;
  source: "gemini" | "fallback";
  fetchWarning?: string;
};

export type GenerateAuditRequest = {
  lead: AeoLead;
  brandName: string;
  website: string;
  consentAccepted: boolean;
  eventCode?: string;
};

export type GenerateAuditResponse =
  | { success: true; report: AeoAuditReport }
  | { success: false; error: string };

export function snapshotFromReport(report: AeoAuditReport): MentionRateSnapshot {
  return {
    brandName: report.brandName,
    website: report.website,
    citationPrompts: report.citationPrompts,
    mentionRates: [...report.mentionRates].sort((a, b) => b.estimatedPct - a.estimatedPct),
    generatedAt: new Date().toISOString(),
  };
}

export function emptyAuditReport(brandName: string, website: string): AeoAuditReport {
  return {
    brandName,
    website,
    primaryCountry: "",
    primaryCountryLabel: "",
    description: "",
    readiness: "Developing",
    readinessSummary: "",
    competitors: [],
    personas: [],
    topics: [],
    prompts: [],
    hypotheses: [],
    citationPrompts: [],
    mentionRates: [],
    visibility: null,
    counts: {
      topics: 0,
      competitors: 0,
      personas: 0,
      prompts: 0,
      nonBrandedPct: 0,
      platforms: 9,
    },
    source: "fallback",
  };
}
